  'ak.zonaInfo': ['Menghapus akun bersifat permanen dan tidak bisa dibatalkan.', 'Deleting your account is permanent and cannot be undone.', 'Memadam akaun adalah kekal dan tidak boleh dibatalkan.', 'Mbusak akun iku permanen lan ora bisa dibatalake.', 'Ngahapus akun téh permanén jeung teu bisa dibatalkeun.', '删除账号是永久性的，无法撤销。', 'アカウントの削除は完全で、元に戻せません。'],
  'ak.hapusJudul': ['Hapus akun ini?', 'Delete this account?', 'Padam akaun ini?', 'Busak akun iki?', 'Hapus akun ieu?', '删除此账号？', 'このアカウントを削除しますか？'],
  'ak.hapusPeringatan': ['Tindakan ini tidak bisa dibatalkan. Akun {username} akan dihapus secara permanen, termasuk:', 'This cannot be undone. The account {username} will be permanently deleted, including:', 'Tindakan ini tidak boleh dibatalkan. Akaun {username} akan dipadam secara kekal, termasuk:', 'Iki ora bisa dibatalake. Akun {username} bakal dibusak kanthi permanen, kalebu:', 'Ieu teu bisa dibatalkeun. Akun {username} bakal dihapus sacara permanén, kaasup:', '此操作无法撤销。账号 {username} 将被永久删除，包括：', 'この操作は元に戻せません。アカウント {username} は完全に削除されます。対象：'],
  'ak.hapusDaftar1': ['Semua catatan dan balasan yang kamu tulis', 'All the notes and replies you wrote', 'Semua catatan dan balasan yang anda tulis', 'Kabeh cathetan lan wangsulan sing sampeyan tulis', 'Sakabéh catetan jeung waleran nu anjeun tulis', '你写的所有笔记和回复', 'あなたが書いたすべてのノートと返信'],
