  'ak.hapusUnduh': ['Unduh dulu data kamu', 'Download your data first', 'Muat turun data anda dahulu', 'Undhuh dhisik data sampeyan', 'Unduh heula data anjeun', '先下载你的数据', '先にデータをダウンロード'],
